@Override
@Transactional(rollbackOn = {Exception.class})
public void updateStockLocationFromProduct(StockLocationLine stockLocationLine, Product product)
    throws AxelorException {

  stockLocationLine = this.updateLocationFromProduct(stockLocationLine, product);
  stockLocationLineRepo.save(stockLocationLine);
}

@Override
public StockLocationLine updateLocationFromProduct(
    StockLocationLine stockLocationLine, Product product) throws AxelorException {
  Unit productUnit = product.getUnit();
  Unit stockLocationUnit = stockLocationLine.getUnit();

  if (productUnit != null && !productUnit.equals(stockLocationUnit)) {
    int scale = appBaseService.getNbDecimalDigitForUnitPrice();
    BigDecimal oldQty = stockLocationLine.getCurrentQty();
    BigDecimal oldAvgPrice = stockLocationLine.getAvgPrice();

    BigDecimal currentQty =
        unitConversionService.convert(
            stockLocationUnit,
            productUnit,
            stockLocationLine.getCurrentQty(),
            stockLocationLine.getCurrentQty().scale(),
            product);
    stockLocationLine.setCurrentQty(currentQty);

    stockLocationLine.setUnit(product.getUnit());
    stockLocationLine.setFutureQty(computeFutureQty(stockLocationLine));

    BigDecimal newAvgPrice = BigDecimal.ZERO;
    if (currentQty.compareTo(BigDecimal.ZERO) != 0) {
      newAvgPrice = oldAvgPrice.multiply(oldQty).divide(currentQty, scale, RoundingMode.HALF_UP);
    }
    stockLocationLine.setAvgPrice(newAvgPrice);
    updateHistory(
        stockLocationLine,
        null,
        null,
        null,
        StockLocationLineHistoryRepository.TYPE_SELECT_UPDATE_STOCK_LOCATION_FROM_PRODUCT);
  }
  return stockLocationLine;
}

@Override
public BigDecimal convertToProductUnit(StockLocationLine stockLocationLine, BigDecimal value)
    throws AxelorException {
  Product product = stockLocationLine.getProduct();
  return convert(stockLocationLine.getUnit(), productUnit(product), value, product);
}

@Override
public BigDecimal convertFromProductUnit(StockLocationLine stockLocationLine, BigDecimal value)
    throws AxelorException {
  Product product = stockLocationLine.getProduct();
  return convert(productUnit(product), stockLocationLine.getUnit(), value, product);
}

protected Unit productUnit(Product product) {
  return product == null ? null : product.getUnit();
}

protected BigDecimal convert(Unit startUnit, Unit endUnit, BigDecimal value, Product product)
    throws AxelorException {
  if (value == null || startUnit == null || endUnit == null || startUnit.equals(endUnit)) {
    return value;
  }
  return unitConversionService.convertWithAutoFlushFalse(
      startUnit, endUnit, value, value.scale(), product);
}

@Override
public BigDecimal computeFutureQty(StockLocationLine stockLocationLine) throws AxelorException {
  // future quantity = current quantity - planned outgoing + planned incoming
  BigDecimal futureQty =
      stockLocationLine.getCurrentQty() != null
          ? stockLocationLine.getCurrentQty()
          : BigDecimal.ZERO;

  Product product = stockLocationLine.getProduct();

  if (stockLocationLine.getUnit() == null) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_CONFIGURATION_ERROR,
        I18n.get(StockExceptionMessage.LOCATION_LINE_MISSING_UNIT),
        stockLocationLine.getStockLocation().getName(),
        product.getFullName());
  }

  boolean isDetailsStockLocationLine = stockLocationLine.getDetailsStockLocation() != null;
  Long stockLocationId =
      isDetailsStockLocationLine
          ? stockLocationLine.getDetailsStockLocation().getId()
          : stockLocationLine.getStockLocation().getId();
  Long trackingNumberId =
      isDetailsStockLocationLine && stockLocationLine.getTrackingNumber() != null
          ? stockLocationLine.getTrackingNumber().getId()
          : null;

  StringBuilder jpql = new StringBuilder();
  jpql.append(
      "SELECT new com.axelor.apps.stock.utils.StockLocationLineQtyView("
          + " self.unit, "
          + " SUM(CASE WHEN self.toStockLocation.id = :stockLocationId THEN COALESCE(self.qty, 0) ELSE 0 END), "
          + " SUM(CASE WHEN self.fromStockLocation.id = :stockLocationId THEN COALESCE(self.qty, 0) ELSE 0 END) "
          + ") "
          + " FROM StockMoveLine self "
          + " WHERE (self.stockMove.archived IS NULL OR self.archived IS FALSE) "
          + " AND self.stockMove.statusSelect = :planned "
          + " AND self.product.id = :productId "
          + " AND (self.toStockLocation.id = :stockLocationId OR self.fromStockLocation.id = :stockLocationId) ");
  if (isDetailsStockLocationLine) {
    jpql.append(" AND self.trackingNumber.id = :trackingNumberId ");
  }
  jpql.append(" GROUP BY self.unit");

  var query =
      JPA.em()
          .createQuery(jpql.toString(), StockLocationLineQtyView.class)
          .setParameter("planned", StockMoveRepository.STATUS_PLANNED)
          .setParameter("productId", product.getId())
          .setParameter("stockLocationId", stockLocationId);
  if (isDetailsStockLocationLine) {
    query.setParameter("trackingNumberId", trackingNumberId);
  }
  query.setFlushMode(FlushModeType.COMMIT);
  List<StockLocationLineQtyView> aggregates = query.getResultList();

  for (StockLocationLineQtyView agg : aggregates) {
    Unit aggUnit = agg.getUnit();
    BigDecimal incoming = agg.getIncoming() != null ? agg.getIncoming() : BigDecimal.ZERO;
    BigDecimal outgoing = agg.getOutgoing() != null ? agg.getOutgoing() : BigDecimal.ZERO;

    if (incoming.compareTo(BigDecimal.ZERO) != 0) {
      BigDecimal incConverted =
          unitConversionService.convertWithAutoFlushFalse(
              aggUnit, stockLocationLine.getUnit(), incoming, incoming.scale(), product);
      futureQty = futureQty.add(incConverted);
    }

    if (outgoing.compareTo(BigDecimal.ZERO) != 0) {
      BigDecimal outConverted =
          unitConversionService.convertWithAutoFlushFalse(
              aggUnit, stockLocationLine.getUnit(), outgoing, outgoing.scale(), product);
      futureQty = futureQty.subtract(outConverted);
    }
  }

  return futureQty;
}

@Override
public void updateHistory(
    StockLocationLine stockLocationLine,
    StockMoveLine stockMoveLine,
    LocalDateTime dateT,
    String origin,
    String typeSelect)
    throws AxelorException {

  if (origin == null) {
    origin =
        Optional.ofNullable(stockMoveLine)
            .map(StockMoveLine::getStockMove)
            .map(StockMove::getStockMoveSeq)
            .orElse("");
  }

  if (dateT == null) {
    Company company = getCompany(stockLocationLine);
    dateT = appBaseService.getTodayDateTime(company).toLocalDateTime();
  }
  stockLocationLineHistoryService.saveHistory(stockLocationLine, dateT, origin, typeSelect);
}

protected Company getCompany(StockLocationLine stockLocationLine) {
  StockLocation stockLocation = stockLocationLine.getStockLocation();
  StockLocation detailsStockLocation = stockLocationLine.getDetailsStockLocation();

  if (stockLocation != null) {
    return stockLocation.getCompany();
  }

  if (detailsStockLocation != null) {
    return detailsStockLocation.getCompany();
  }
  return Optional.ofNullable(AuthUtils.getUser()).map(User::getActiveCompany).orElse(null);
}

def validate_voucher(self) -> None:
	if self.voucher_type == "Sales Order" and not frappe.get_single_value(
		"Stock Settings", "enable_stock_reservation"
	):
		frappe.throw(
			_("Please enable {0} in the {1}.").format(
				frappe.bold(_("Stock Reservation")), frappe.bold(_("Stock Settings"))
			)
		)

	if frappe.db.get_value(self.voucher_type, self.voucher_no, "docstatus") != 1:
		frappe.throw(
			_("{0} {1} must be submitted to reserve stock against it.").format(
				_(self.voucher_type), frappe.bold(self.voucher_no)
			)
		)

	if self.voucher_type == "Sales Order" and not self.is_row_of_voucher():
		frappe.throw(
			_("Item {0} is not a row of {1} {2}.").format(
				frappe.bold(self.item_code), _(self.voucher_type), frappe.bold(self.voucher_no)
			)
		)

def is_row_of_voucher(self) -> bool:
	filters = {"name": self.voucher_detail_no, "parent": self.voucher_no, "item_code": self.item_code}
	return bool(frappe.db.exists("Sales Order Item", filters) or frappe.db.exists("Packed Item", filters))

def before_cancel(self) -> None:
	self.validate_reserved_entries()
	self.validate_work_order_usage()

def validate_work_order_usage(self) -> None:
	"""Stock a Work Order has transferred or consumed is released by closing the Work Order, not by cancelling its reservation."""
	if self.voucher_type != "Work Order" or not (flt(self.transferred_qty) or flt(self.consumed_qty)):
		return

	if frappe.db.get_value("Work Order", self.voucher_no, "status") in ("Closed", "Cancelled"):
		return

	if (
		self.from_voucher_type == "Stock Entry"
		and frappe.db.get_value("Stock Entry", self.from_voucher_no, "docstatus") == 2
	):
		return

	frappe.throw(
		_(
			"Stock Reservation Entry {0} is already used by Work Order {1}. Close the Work Order to release the unused stock."
		).format(frappe.bold(self.name), frappe.bold(self.voucher_no))
	)

def validate_reserved_entries(self):
	entries = frappe.get_all(
		"Stock Reservation Entry",
		fields=["voucher_no as name"],
		filters={
			"status": "Closed",
			"docstatus": 1,
			"from_voucher_type": "Purchase Receipt",
			"from_voucher_no": self.from_voucher_no,
		},
	)

	if entries:
		work_orders = frappe.get_all(
			"Work Order",
			fields=["name"],
			filters={"production_plan": ("in", [entry.name for entry in entries])},
		)

		frappe.throw(
			_(
				"Cannot cancel Stock Reservation Entry {0}, as it has used in the work order {1}. Please cancel the work order first or unreserved the stock"
			).format(
				", ".join([frappe.bold(entry.name) for entry in entries]),
				", ".join([frappe.bold(wo.name) for wo in work_orders]),
			)
		)

def update_unreserved_qty_in_sre(self):
	if self.voucher_type != "Delivery Note":
		self.give_back_to_from_voucher(self.get_serial_batch_entries())

def give_back_to_from_voucher(self, released: frappe._dict) -> None:
	"""Return `released` serial and batch qty to the reservations this one was taken from and recount them."""
	if not (self.from_voucher_type and self.from_voucher_detail_no):
		return

	if self.has_batch_no or self.has_serial_no:
		self.give_back_serial_batch(released)

	self.update_delivered_qty_in_from_voucher_reservations()

def update_delivered_qty_in_from_voucher_reservations(self):
	"""Recount the delivered qty of the reservations this one was taken from, each by its own reservation mode."""
	sres = self.get_from_voucher_reservation_entries()
	open_qty = get_serial_batch_open_qty([row.name for row in sres])
	counted_qty = 0.0
	for row in sres:
		if row.name in open_qty:
			delivered_qty = row.reserved_qty - open_qty[row.name]
			set_delivered_qty(row, delivered_qty)
			counted_qty += delivered_qty

	self.spread_used_qty([row for row in sres if row.name not in open_qty], counted_qty)

	for warehouse in {row.warehouse for row in sres}:
		frappe.get_cached_doc("Bin", get_or_make_bin(self.item_code, warehouse)).update_reserved_stock()

def give_back_serial_batch(self, released: frappe._dict) -> None:
	"""Lower the delivered serial and batch qty of the source reservations by `released` once."""
	sources = self.get_from_voucher_reservation_entries()
	move_serial_batch_delivered_qty(
		{row.name: row.delivered_qty for row in sources}, released, release=True
	)

def get_delivered_serial_batch_entries(self) -> frappe._dict:
	serial_nos = []
	batches = defaultdict(float)
	for entry in self.sb_entries:
		if entry.serial_no and flt(entry.delivered_qty):
			serial_nos.append(entry.serial_no)
		elif entry.batch_no:
			batches[entry.batch_no] += flt(entry.delivered_qty)

	return frappe._dict({"serial_nos": serial_nos, "batches": batches})

def get_serial_batch_entries(self):
	serial_nos = []
	batches = defaultdict(float)
	for entry in self.sb_entries:
		if entry.serial_no:
			if flt(entry.qty) and not flt(entry.delivered_qty):
				serial_nos.append(entry.serial_no)
		elif entry.batch_no:
			batches[entry.batch_no] += flt(entry.qty) - flt(entry.delivered_qty)

	return frappe._dict(
		{
			"serial_nos": serial_nos,
			"batches": batches,
		}
	)

def validate_amended_doc(self) -> None:
	"""Raises an exception if document is amended."""

	if self.amended_from:
		msg = _("Cannot amend {0} {1}, please create a new one instead.").format(
			self.doctype, frappe.bold(self.amended_from)
		)
		frappe.throw(msg)

def validate_group_warehouse(self) -> None:
	"""Raises an exception if `Warehouse` is a Group Warehouse."""

	if frappe.get_cached_value("Warehouse", self.warehouse, "is_group"):
		msg = _("Stock cannot be reserved in group warehouse {0}.").format(frappe.bold(self.warehouse))
		frappe.throw(msg, title=_("Invalid Warehouse"))

def validate_uom_is_integer(self) -> None:
	"""Validates `Reserved Qty` with Stock UOM."""

	if cint(frappe.db.get_value("UOM", self.stock_uom, "must_be_whole_number", cache=True)):
		if cint(self.reserved_qty) != flt(self.reserved_qty, self.precision("reserved_qty")):
			msg = _(
				"Reserved Qty ({0}) cannot be a fraction. To allow this, disable '{1}' in UOM {3}."
			).format(
				flt(self.reserved_qty, self.precision("reserved_qty")),
				frappe.bold(_("Must be Whole Number")),
				frappe.bold(self.stock_uom),
			)
			frappe.throw(msg)

def set_reservation_based_on(self) -> None:
	"""Sets `Reservation Based On` based on `Has Serial No` and `Has Batch No`."""

	if (self.reservation_based_on == "Serial and Batch") and (
		not self.has_serial_no and not self.has_batch_no
	):
		self.db_set("reservation_based_on", "Qty")

def validate_reservation_based_on_qty(self) -> None:
	"""Validates `Reserved Qty` when `Reservation Based On` is `Qty`."""

	if self.reservation_based_on == "Qty" and self.voucher_type != "Subcontracting Inward Order":
		self.validate_with_allowed_qty(self.reserved_qty)

def auto_reserve_serial_and_batch(self, based_on: str | None = None) -> None:
	"""Auto pick Serial and Batch Nos to reserve when `Reservation Based On` is `Serial and Batch`."""
	if (
		not self.from_voucher_type
		and (self.get("_action") == "submit")
		and (self.has_serial_no or self.has_batch_no)
		and frappe.get_single_value("Stock Settings", "auto_reserve_serial_and_batch")
		and not self.sb_entries
	):
		from erpnext.stock.doctype.batch.batch import get_available_batches
		from erpnext.stock.doctype.serial_no.serial_no import get_serial_nos_for_outward
		from erpnext.stock.serial_batch_bundle import get_serial_nos_batch

		self.reservation_based_on = "Serial and Batch"
		self.sb_entries.clear()
		kwargs = frappe._dict(
			{
				"item_code": self.item_code,
				"warehouse": self.warehouse,
				"qty": abs(self.reserved_qty) or 0,
				"based_on": based_on
				or frappe.get_single_value("Stock Settings", "pick_serial_and_batch_based_on"),
			}
		)

		serial_nos, batch_nos = [], []
		if self.has_serial_no:
			serial_nos = get_serial_nos_for_outward(kwargs)
		if self.has_batch_no:
			batch_nos = get_available_batches(kwargs)

		if serial_nos:
			serial_no_wise_batch = frappe._dict({})

			if self.has_batch_no:
				serial_no_wise_batch = get_serial_nos_batch(serial_nos)

			for serial_no in serial_nos:
				self.append(
					"sb_entries",
					{
						"serial_no": serial_no,
						"qty": 1,
						"batch_no": serial_no_wise_batch.get(serial_no),
						"warehouse": self.warehouse,
					},
				)
		elif batch_nos:
			for batch_no, batch_qty in batch_nos.items():
				self.append(
					"sb_entries",
					{
						"batch_no": batch_no,
						"qty": batch_qty,
						"warehouse": self.warehouse,
					},
				)

def validate_reservation_based_on_serial_and_batch(self) -> None:
	"""Validates `Reserved Qty`, `Serial and Batch Nos` when `Reservation Based On` is `Serial and Batch`."""
	is_production_voucher = self.voucher_type in ["Work Order", "Subcontracting Order"]
	if is_production_voucher:
		if self.from_voucher_type:
			return

		self.validate_with_allowed_qty(self.reserved_qty)
		if not self.sb_entries:
			return

	if self.reservation_based_on == "Serial and Batch":
		allow_partial_reservation = frappe.get_single_value("Stock Settings", "allow_partial_reservation")

		available_serial_nos = []
		if self.has_serial_no:
			available_serial_nos = get_available_serial_nos_to_reserve(
				self.item_code, self.warehouse, self.has_batch_no, ignore_sre=self.name
			)

			if not available_serial_nos:
				msg = _("Stock not available for Item {0} in Warehouse {1}.").format(
					frappe.bold(self.item_code), frappe.bold(self.warehouse)
				)
				frappe.throw(msg)

		qty_to_be_reserved = 0
		selected_batch_nos, selected_serial_nos = [], []
		for entry in self.sb_entries:
			entry.warehouse = self.warehouse

			if self.has_serial_no:
				entry.qty = 1

				key = (
					(entry.serial_no, self.warehouse, entry.batch_no)
					if self.has_batch_no
					else (entry.serial_no, self.warehouse)
				)
				if key not in available_serial_nos:
					msg = _(
						"Row #{0}: Serial No {1} for Item {2} is not available in {3} {4} or might be reserved in another {5}."
					).format(
						entry.idx,
						frappe.bold(entry.serial_no),
						frappe.bold(self.item_code),
						_("Batch {0} and Warehouse").format(frappe.bold(entry.batch_no))
						if self.has_batch_no
						else _("Warehouse"),
						frappe.bold(self.warehouse),
						frappe.bold(_("Stock Reservation Entry")),
					)

					frappe.throw(msg)

				if entry.serial_no in selected_serial_nos:
					msg = _("Row #{0}: Serial No {1} is already selected.").format(
						entry.idx, frappe.bold(entry.serial_no)
					)
					frappe.throw(msg)
				else:
					selected_serial_nos.append(entry.serial_no)

			elif self.has_batch_no:
				if cint(frappe.db.get_value("Batch", entry.batch_no, "disabled")):
					msg = _(
						"Row #{0}: Stock cannot be reserved for Item {1} against a disabled Batch {2}."
					).format(entry.idx, frappe.bold(self.item_code), frappe.bold(entry.batch_no))
					frappe.throw(msg)

				available_qty_to_reserve = get_available_qty_to_reserve(
					self.item_code, self.warehouse, entry.batch_no, ignore_sre=self.name
				)

				if available_qty_to_reserve <= 0:
					msg = _(
						"Row #{0}: Stock not available to reserve for Item {1} against Batch {2} in Warehouse {3}."
					).format(
						entry.idx,
						frappe.bold(self.item_code),
						frappe.bold(entry.batch_no),
						frappe.bold(self.warehouse),
					)
					frappe.throw(msg)

				if entry.qty > available_qty_to_reserve:
					if allow_partial_reservation:
						entry.qty = available_qty_to_reserve
						if self.get("_action") == "update_after_submit":
							entry.db_update()
					else:
						msg = _(
							"Row #{0}: Qty should be less than or equal to Available Qty to Reserve (Actual Qty - Reserved Qty) {1} for Iem {2} against Batch {3} in Warehouse {4}."
						).format(
							entry.idx,
							frappe.bold(available_qty_to_reserve),
							frappe.bold(self.item_code),
							frappe.bold(entry.batch_no),
							frappe.bold(self.warehouse),
						)
						frappe.throw(msg)

				if entry.batch_no in selected_batch_nos:
					msg = _("Row #{0}: Batch No {1} is already selected.").format(
						entry.idx, frappe.bold(entry.batch_no)
					)
					frappe.throw(msg)
				else:
					selected_batch_nos.append(entry.batch_no)

			qty_to_be_reserved += entry.qty

		if not qty_to_be_reserved:
			msg = _("Please select Serial/Batch Nos to reserve or change Reservation Based On to Qty.")
			frappe.throw(msg)

		if is_production_voucher:
			return

		# Should be called after validating Serial and Batch Nos.
		if self.voucher_type != "Subcontracting Inward Order":
			self.validate_with_allowed_qty(qty_to_be_reserved)
		self.db_set("reserved_qty", qty_to_be_reserved)

def update_reserved_qty_in_voucher(
	self, reserved_qty_field: str = "stock_reserved_qty", update_modified: bool = True
) -> None:
	"""Updates total reserved qty in the voucher."""

	item_doctype = {
		"Sales Order": "Sales Order Item",
		"Work Order": "Work Order Item",
		"Production Plan": "Production Plan Sub Assembly Item",
		"Subcontracting Order": "Subcontracting Order Supplied Item",
	}.get(self.voucher_type, None)

	if item_doctype:
		sre = frappe.qb.DocType("Stock Reservation Entry")
		reserved_qty = (
			frappe.qb.from_(sre)
			.select(Sum(sre.reserved_qty - sre.delivered_qty - sre.transferred_qty - sre.consumed_qty))
			.where(
				(sre.docstatus == 1)
				& (sre.voucher_type == self.voucher_type)
				& (sre.voucher_no == self.voucher_no)
				& (sre.voucher_detail_no == self.voucher_detail_no)
			)
		).run(as_list=True)[0][0] or 0

		if self.voucher_type == "Production Plan" and frappe.db.exists(
			"Material Request Plan Item", self.voucher_detail_no
		):
			item_doctype = "Material Request Plan Item"

		frappe.db.set_value(
			item_doctype,
			self.voucher_detail_no,
			reserved_qty_field,
			reserved_qty,
			update_modified=update_modified,
		)

def update_status(self, status: str | None = None, update_modified: bool = True) -> None:
	"""Updates status based on Voucher Qty, Reserved Qty and Delivered Qty."""
	frappe.db.set_value(
		self.doctype, self.name, "status", status or get_status(self), update_modified=update_modified
	)

def can_be_updated(self) -> None:
	"""Raises an exception if `Stock Reservation Entry` is not allowed to be updated."""

	if self.status in ("Partially Delivered", "Delivered"):
		msg = _(
			"{0} {1} cannot be updated. If you need to make changes, we recommend canceling the existing entry and creating a new one."
		).format(self.status, self.doctype)
		frappe.throw(msg)

	if self.from_voucher_type == "Pick List":
		msg = _(
			"Stock Reservation Entry created against a Pick List cannot be updated. If you need to make changes, we recommend canceling the existing entry and creating a new one."
		)
		frappe.throw(msg)

	if self.delivered_qty > 0:
		msg = _("Stock Reservation Entry cannot be updated as it has been delivered.")
		frappe.throw(msg)

def get_total_reserved_qty(self) -> float:
	"""Returns the qty other entries hold against the voucher row."""
	if self.voucher_type in ["Work Order", "Subcontracting Order"] and not self.from_voucher_type:
		return self.get_row_reserved_qty()

	from_voucher_detail_no = None
	if self.from_voucher_type in ["Stock Entry", "Production Plan"]:
		from_voucher_detail_no = self.from_voucher_detail_no

	return get_sre_reserved_qty_for_voucher_detail_no(
		self.item_code,
		self.voucher_type,
		self.voucher_no,
		self.voucher_detail_no,
		ignore_sre=self.name,
		warehouse=None if self.voucher_type == "Sales Order" else self.warehouse,
		from_voucher_detail_no=from_voucher_detail_no,
	)

def consume_serial_batch_for_material_transfer(self, row_wise_serial_batch):
	for entry in self.sb_entries:
		entry.delivered_qty = 0

	for entry in self.sb_entries:
		for row in row_wise_serial_batch:
			data = row_wise_serial_batch[row]

			if entry.serial_no in data.serial_nos:
				entry.delivered_qty = flt(1)

			elif not entry.serial_no and entry.batch_no in data.batch_nos:
				entry.delivered_qty = flt(data.batch_nos[entry.batch_no])

		entry.db_update()

def validate_stock_reservation_settings(voucher: object) -> None:
	"""Raises an exception if `Stock Reservation` is not enabled or `Voucher Type` is not allowed."""

	if not frappe.get_single_value("Stock Settings", "enable_stock_reservation"):
		msg = _("Please enable {0} in the {1}.").format(
			frappe.bold(_("Stock Reservation")),
			frappe.bold(_("Stock Settings")),
		)
		frappe.throw(msg)

	# Voucher types allowed for stock reservation
	allowed_voucher_types = ["Sales Order"]

	if voucher.doctype not in allowed_voucher_types:
		msg = _("Stock Reservation can only be created against {0}.").format(", ".join(allowed_voucher_types))
		frappe.throw(msg)

def get_available_qty_to_reserve(
	item_code: str, warehouse: str, batch_no: str | None = None, ignore_sre=None
) -> float:
	"""Returns `Available Qty to Reserve (Actual Qty - Reserved Qty)` for Item, Warehouse and Batch combination."""

	from erpnext.stock.doctype.batch.batch import get_batch_qty

	if batch_no:
		return get_batch_qty(
			item_code=item_code,
			warehouse=warehouse,
			batch_no=batch_no,
			ignore_voucher_nos=[ignore_sre] if ignore_sre else None,
		)

	available_qty = _get_stock_balance(item_code, warehouse)

	if available_qty:
		sre = frappe.qb.DocType("Stock Reservation Entry")
		query = (
			frappe.qb.from_(sre)
			.select(Sum(sre.reserved_qty - sre.delivered_qty - sre.transferred_qty - sre.consumed_qty))
			.where(
				(sre.docstatus == 1)
				& (sre.item_code == item_code)
				& (sre.warehouse == warehouse)
				& (sre.delivered_qty < sre.reserved_qty)
			)
			.for_update()
		)

		if ignore_sre:
			query = query.where(sre.name != ignore_sre)

		reserved_qty = query.run()[0][0] or 0.0

		if reserved_qty:
			return available_qty - reserved_qty

	return available_qty

def get_available_serial_nos_to_reserve(
	item_code: str, warehouse: str, has_batch_no: bool = False, ignore_sre=None
) -> list[tuple]:
	"""Returns Available Serial Nos to Reserve (Available Serial Nos - Reserved Serial Nos)` for Item, Warehouse and Batch combination."""

	from erpnext.stock.doctype.serial_and_batch_bundle.serial_and_batch_bundle import (
		get_available_serial_nos,
	)

	available_serial_nos = get_available_serial_nos(
		frappe._dict(
			{
				"item_code": item_code,
				"warehouse": warehouse,
				"has_batch_no": has_batch_no,
				"ignore_voucher_nos": [ignore_sre],
			}
		)
	)

	available_serial_nos_list = []
	if available_serial_nos:
		available_serial_nos_list = [tuple(d.values()) for d in available_serial_nos]

		sre = frappe.qb.DocType("Stock Reservation Entry")
		sb_entry = frappe.qb.DocType("Serial and Batch Entry")
		query = (
			frappe.qb.from_(sre)
			.left_join(sb_entry)
			.on(sre.name == sb_entry.parent)
			.select(sb_entry.serial_no, sre.warehouse)
			.where(
				(sre.docstatus == 1)
				& (sre.item_code == item_code)
				& (sre.warehouse == warehouse)
				& (sre.delivered_qty < sre.reserved_qty)
				& (sre.reservation_based_on == "Serial and Batch")
			)
		)

		if has_batch_no:
			query = query.select(sb_entry.batch_no)

		if ignore_sre:
			query = query.where(sre.name != ignore_sre)

		reserved_serial_nos = query.run()

		if reserved_serial_nos:
			return list(set(available_serial_nos_list) - set(reserved_serial_nos))

	return available_serial_nos_list

def get_sre_reserved_qty_for_items_and_warehouses(
	item_code_list: list, warehouse_list: list | None = None
) -> dict:
	"""Returns a dict like {("item_code", "warehouse"): "reserved_qty", ... }."""

	if not item_code_list:
		return {}

	sre = frappe.qb.DocType("Stock Reservation Entry")
	query = (
		frappe.qb.from_(sre)
		.select(
			sre.item_code,
			sre.warehouse,
			Sum(sre.reserved_qty - sre.delivered_qty - sre.transferred_qty - sre.consumed_qty).as_(
				"reserved_qty"
			),
		)
		.where(
			(sre.docstatus == 1)
			& sre.item_code.isin(item_code_list)
			& (sre.delivered_qty < sre.reserved_qty)
			& (sre.status.notin(["Closed", "Delivered"]))
		)
		.groupby(sre.item_code, sre.warehouse)
	)

	if warehouse_list:
		query = query.where(sre.warehouse.isin(warehouse_list))

	data = query.run(as_dict=True)

	return {(d["item_code"], d["warehouse"]): d["reserved_qty"] for d in data} if data else {}

def get_whole_sales_unit_qty(item, stock_qty: float, max_qty: float | None = None) -> float:
	conversion_factor = flt(item.get("conversion_factor")) or 1
	if conversion_factor == 1 or not frappe.get_cached_value("UOM", item.get("uom"), "must_be_whole_number"):
		return stock_qty

	if max_qty is not None:
		stock_qty = min(ceil(flt(flt(stock_qty) / conversion_factor, 6)) * conversion_factor, max_qty)

	return floor(flt(flt(stock_qty) / conversion_factor, 6)) * conversion_factor

def has_reserved_stock(voucher_type: str, voucher_no: str, voucher_detail_no: str | None = None) -> bool:
	"""Returns True if there is any Stock Reservation Entry for the given voucher."""

	if _get_stock_reservation_entries_for_voucher(
		voucher_type, voucher_no, voucher_detail_no, fields=["name"], ignore_status=True
	):
		return True

	return False

def initialize_fields(self) -> None:
	self.table_name = "items"
	self.qty_field = "stock_qty"
	self.warehouse_field = "warehouse"
	self.warehouse = None

	if self.doc.doctype == "Work Order":
		self.table_name = "required_items"
		self.qty_field = "required_qty"
		self.warehouse_field = "source_warehouse"
		if self.doc.skip_transfer and self.doc.from_wip_warehouse:
			self.warehouse = self.doc.wip_warehouse
	elif self.doc.doctype == "Subcontracting Order":
		self.table_name = "supplied_items"
		self.qty_field = "required_qty"
	elif self.doc.doctype == "Production Plan" and self.kwargs:
		for key, value in self.kwargs.items():
			setattr(self, key, value)

def cancel_stock_reservation_entries(self, names=None) -> None:
	"""Cancels Stock Reservation Entries for the Voucher."""

	if isinstance(names, str):
		names = parse_json(names)

	sre = frappe.qb.DocType("Stock Reservation Entry")
	query = (
		frappe.qb.from_(sre)
		.select(sre.name)
		.where(
			(sre.docstatus == 1)
			& (sre.voucher_type == self.doc.doctype)
			& (sre.voucher_no == self.doc.name)
		)
	)

	if names:
		query = query.where(sre.name.isin(names))
	elif self.warehouse:
		query = query.where(sre.warehouse == self.warehouse)

	sre_names = query.run(as_dict=True)

	if sre_names:
		for sre_name in sre_names:
			sre_doc = frappe.get_doc("Stock Reservation Entry", sre_name.name)
			sre_doc.flags.ignore_permissions = True
			sre_doc.cancel()

	if sre_names and names:
		frappe.msgprint(
			_("Stock has been unreserved for work order {0}.").format(frappe.bold(self.doc.name)),
			alert=True,
		)

def get_voucher_qty(self, item, voucher_detail_no):
	"""Returns the voucher row's full requirement, unless the limit is scoped to the source row."""
	if item.get("from_voucher_type") in ["Stock Entry", "Production Plan"]:
		return None

	rows = self.doc.get(self.table_name, {"name": voucher_detail_no})
	return rows[0].get(self.qty_field) if rows else None

def set_serial_batch(self, sre, serial_batch_bundles):
	bundle_details = frappe.get_all(
		"Serial and Batch Entry",
		fields=["serial_no", "batch_no", "qty"],
		filters={"parent": ("in", serial_batch_bundles)},
		order_by="creation",
	)

	for detail in bundle_details:
		sre.append(
			"sb_entries",
			{
				"serial_no": detail.serial_no,
				"batch_no": detail.batch_no,
				"qty": abs(detail.qty),
				"warehouse": sre.warehouse,
			},
		)

def throw_stock_not_exists_error(self, idx, item_code, warehouse):
	if idx:
		msg = _("Row #{0}: Stock not available to reserve for the Item {1} in Warehouse {2}.").format(
			idx, frappe.bold(item_code), frappe.bold(warehouse)
		)
	else:
		msg = _("Stock not available to reserve for the Item {0} in Warehouse {1}.").format(
			frappe.bold(item_code), frappe.bold(warehouse)
		)

	frappe.msgprint(msg, title=_("Stock Reservation"), indicator="orange")

def get_available_qty_to_reserve(self, item_code, warehouse, ignore_sre=None):
	available_qty = _get_stock_balance(item_code, warehouse)

	if available_qty:
		sre = frappe.qb.DocType("Stock Reservation Entry")
		query = (
			frappe.qb.from_(sre)
			.select(Sum(sre.reserved_qty - sre.delivered_qty - sre.transferred_qty - sre.consumed_qty))
			.where(
				(sre.docstatus == 1)
				& (sre.item_code == item_code)
				& (sre.warehouse == warehouse)
				& (sre.delivered_qty < sre.reserved_qty)
			)
		)

		if ignore_sre:
			query = query.where(sre.name != ignore_sre)

		reserved_qty = query.run()[0][0] or 0.0

		if reserved_qty:
			return available_qty - reserved_qty

	return available_qty

def update_delivered_qty(self, data):
	for name, delivered_qty in data.get("sre_names").items():
		doctype = frappe.qb.DocType("Stock Reservation Entry")
		query = (
			frappe.qb.update(doctype)
			.set(doctype.delivered_qty, doctype.delivered_qty + delivered_qty)
			.set(
				doctype.status,
				Case().when((doctype.reserved_qty == doctype.delivered_qty), "Closed").else_("Reserved"),
			)
			.where(doctype.name == name)
		)

		query.run()

	if data.serial_nos or data.batches:
		move_serial_batch_delivered_qty(data.get("sre_names"), data)

def create_stock_reservation_entries_for_so_items(
	sales_order: object,
	items_details: list[dict] | None = None,
	from_voucher_type: Literal["Pick List", "Purchase Receipt"] = None,
	notify=True,
) -> None:
	"""Creates Stock Reservation Entries for Sales Order Items."""

	from erpnext.selling.doctype.sales_order.sales_order import get_unreserved_qty

	if not from_voucher_type and (
		sales_order.get("_action") == "submit"
		and sales_order.set_warehouse
		and cint(frappe.get_cached_value("Warehouse", sales_order.set_warehouse, "is_group"))
	):
		return frappe.msgprint(
			_("Stock cannot be reserved in the group warehouse {0}.").format(
				frappe.bold(sales_order.set_warehouse)
			)
		)

	validate_stock_reservation_settings(sales_order)

	allow_partial_reservation = frappe.get_single_value("Stock Settings", "allow_partial_reservation")

	items = []
	if items_details:
		for item in items_details:
			so_item = frappe.get_doc("Sales Order Item", item.get("sales_order_item"))
			if so_item.parent != sales_order.name:
				frappe.throw(
					_("Sales Order Item {0} does not belong to {1}").format(so_item.name, sales_order.name)
				)

			so_item.warehouse = item.get("warehouse")
			so_item.qty_to_reserve = (
				flt(item.get("qty_to_reserve"))
				if from_voucher_type in ["Pick List", "Purchase Receipt"]
				else (
					flt(item.get("qty_to_reserve"))
					* (flt(item.get("conversion_factor")) or flt(so_item.conversion_factor) or 1)
				)
			)
			so_item.from_voucher_no = item.get("from_voucher_no")
			so_item.from_voucher_detail_no = item.get("from_voucher_detail_no")
			so_item.serial_and_batch_bundle = item.get("serial_and_batch_bundle")

			items.append(so_item)

	sre_count = 0
	reserved_qty_details = get_sre_reserved_qty_details_for_voucher("Sales Order", sales_order.name)

	for item in items if items_details else sales_order.get("items"):
		# Skip if `Reserved Stock` is not checked for the item.
		if not item.get("reserve_stock"):
			continue

		# Stock should be reserved from the Pick List if has Picked Qty.
		if from_voucher_type != "Pick List" and flt(item.picked_qty) > 0:
			frappe.throw(
				_("Row #{0}: Item {1} has been picked, please reserve stock from the Pick List.").format(
					item.idx, frappe.bold(item.item_code)
				)
			)

		is_stock_item, has_serial_no, has_batch_no = frappe.get_cached_value(
			"Item", item.item_code, ["is_stock_item", "has_serial_no", "has_batch_no"]
		)

		# Skip if Non-Stock Item.
		if not is_stock_item:
			if not from_voucher_type:
				frappe.msgprint(
					_("Row #{0}: Stock cannot be reserved for a non-stock Item {1}").format(
						item.idx, frappe.bold(item.item_code)
					),
					title=_("Stock Reservation"),
					indicator="yellow",
				)

			item.db_set("reserve_stock", 0)
			continue

		# Skip if Group Warehouse.
		if frappe.get_cached_value("Warehouse", item.warehouse, "is_group"):
			frappe.msgprint(
				_("Row #{0}: Stock cannot be reserved in group warehouse {1}.").format(
					item.idx, frappe.bold(item.warehouse)
				),
				title=_("Stock Reservation"),
				indicator="yellow",
			)
			continue

		unreserved_qty = get_unreserved_qty(item, reserved_qty_details)

		# Stock is already reserved for the item, notify the user and skip the item.
		if unreserved_qty <= 0:
			if not from_voucher_type:
				frappe.msgprint(
					_("Row #{0}: Stock is already reserved for the Item {1}.").format(
						item.idx, frappe.bold(item.item_code)
					),
					title=_("Stock Reservation"),
					indicator="yellow",
				)

			continue

		available_qty_to_reserve = get_available_qty_to_reserve(item.item_code, item.warehouse)

		# No stock available to reserve, notify the user and skip the item.
		if available_qty_to_reserve <= 0:
			frappe.msgprint(
				_("Row #{0}: Stock not available to reserve for the Item {1} in Warehouse {2}.").format(
					item.idx, frappe.bold(item.item_code), frappe.bold(item.warehouse)
				),
				title=_("Stock Reservation"),
				indicator="orange",
			)
			continue

		# The quantity which can be reserved.
		qty_to_be_reserved = min(unreserved_qty, available_qty_to_reserve)

		if hasattr(item, "qty_to_reserve"):
			if item.qty_to_reserve <= 0:
				frappe.msgprint(
					_("Row #{0}: Quantity to reserve for the Item {1} should be greater than 0.").format(
						item.idx, frappe.bold(item.item_code)
					),
					title=_("Stock Reservation"),
					indicator="orange",
				)
				continue
			else:
				qty_to_be_reserved = min(qty_to_be_reserved, item.qty_to_reserve)

		qty_to_be_reserved = get_whole_sales_unit_qty(
			item,
			qty_to_be_reserved,
			min(unreserved_qty, available_qty_to_reserve)
			if from_voucher_type == "Purchase Receipt"
			else None,
		)
		if not qty_to_be_reserved:
			continue

		# Partial Reservation
		if qty_to_be_reserved < unreserved_qty:
			if not from_voucher_type and (
				not item.get("qty_to_reserve") or qty_to_be_reserved < flt(item.get("qty_to_reserve"))
			):
				msg = _("Row #{0}: Only {1} available to reserve for the Item {2}").format(
					item.idx,
					frappe.bold(str(qty_to_be_reserved / item.conversion_factor) + " " + item.uom),
					frappe.bold(item.item_code),
				)
				frappe.msgprint(msg, title=_("Stock Reservation"), indicator="orange")

			# Skip the item if `Partial Reservation` is disabled in the Stock Settings.
			if not allow_partial_reservation:
				if qty_to_be_reserved == flt(item.get("qty_to_reserve")):
					msg = _(
						"Enable Allow Partial Reservation in the Stock Settings to reserve partial stock."
					)
					frappe.msgprint(msg, title=_("Partial Stock Reservation"), indicator="yellow")

				continue

		sre = frappe.new_doc("Stock Reservation Entry")

		sre.item_code = item.item_code
		sre.warehouse = item.warehouse
		sre.has_serial_no = has_serial_no
		sre.has_batch_no = has_batch_no
		sre.voucher_type = sales_order.doctype
		sre.voucher_no = sales_order.name
		sre.voucher_detail_no = item.name
		sre.available_qty = available_qty_to_reserve
		sre.voucher_qty = item.stock_qty
		sre.reserved_qty = qty_to_be_reserved
		sre.company = sales_order.company
		sre.stock_uom = item.stock_uom
		sre.project = sales_order.project

		if from_voucher_type:
			sre.from_voucher_type = from_voucher_type
			sre.from_voucher_no = item.from_voucher_no
			sre.from_voucher_detail_no = item.from_voucher_detail_no

		if item.get("serial_and_batch_bundle"):
			sre.reservation_based_on = "Serial and Batch"
			set_reserved_serial_batch_entries(
				sre, item.serial_and_batch_bundle, qty_to_be_reserved, has_serial_no, has_batch_no
			)

		sre.save()
		sre.submit()

		sre_count += 1

	if sre_count and notify:
		frappe.msgprint(_("Stock Reservation Entries Created"), alert=True, indicator="green")

def set_reserved_serial_batch_entries(sre, bundle, qty_to_reserve, has_serial_no, has_batch_no):
	picked_qty = 0
	for entry in frappe.get_doc("Serial and Batch Bundle", bundle).entries:
		if picked_qty >= qty_to_reserve:
			break

		qty = 1 if has_serial_no else min(abs(entry.qty), qty_to_reserve - picked_qty)
		sre.append(
			"sb_entries",
			{
				"serial_no": entry.serial_no,
				"batch_no": entry.batch_no,
				"qty": qty,
				"warehouse": entry.warehouse,
			},
		)
		picked_qty += qty

	if picked_qty < qty_to_reserve:
		add_available_serial_batch_entries(sre, qty_to_reserve - picked_qty, has_serial_no, has_batch_no)

def add_available_serial_batch_entries(sre, qty_needed, has_serial_no, has_batch_no):
	if has_serial_no:
		add_available_serial_entries(sre, qty_needed, has_batch_no)
	else:
		add_available_batch_entries(sre, qty_needed)

def add_available_serial_entries(sre, qty_needed, has_batch_no):
	taken = {row.serial_no for row in sre.sb_entries}
	for serial in get_available_serial_nos_to_reserve(sre.item_code, sre.warehouse, has_batch_no):
		if qty_needed <= 0:
			return
		if serial[0] in taken:
			continue

		batch_no = serial[2] if has_batch_no and len(serial) > 2 else None
		sre.append(
			"sb_entries", {"serial_no": serial[0], "batch_no": batch_no, "qty": 1, "warehouse": sre.warehouse}
		)
		qty_needed -= 1

def add_available_batch_entries(sre, qty_needed):
	from erpnext.stock.doctype.serial_and_batch_bundle.serial_and_batch_bundle import get_auto_batch_nos

	taken = {}
	for row in sre.sb_entries:
		taken[row.batch_no] = taken.get(row.batch_no, 0) + flt(row.qty)

	for batch in get_auto_batch_nos(frappe._dict(item_code=sre.item_code, warehouse=sre.warehouse)):
		qty = min(flt(batch.qty) - taken.get(batch.batch_no, 0), qty_needed)
		if qty <= 0:
			continue

		if existing := next((row for row in sre.sb_entries if row.batch_no == batch.batch_no), None):
			existing.qty = flt(existing.qty) + qty
		else:
			sre.append("sb_entries", {"batch_no": batch.batch_no, "qty": qty, "warehouse": sre.warehouse})
		qty_needed -= qty
		if qty_needed <= 0:
			return

def cancel_stock_reservation_entries(
	voucher_type: str | None = None,
	voucher_no: str | None = None,
	voucher_detail_no: str | None = None,
	from_voucher_type: Literal["Pick List", "Purchase Receipt"] = None,
	from_voucher_no: str | None = None,
	from_voucher_detail_no: str | None = None,
	sre_list: list | None = None,
	notify: bool = True,
) -> None:
	"""Cancel Stock Reservation Entries."""

	if not sre_list:
		sre_list = {}

		if voucher_type and voucher_no:
			sre_list = _get_stock_reservation_entries_for_voucher(
				voucher_type, voucher_no, voucher_detail_no, fields=["name"]
			)
		elif from_voucher_type and from_voucher_no:
			sre = frappe.qb.DocType("Stock Reservation Entry")
			query = (
				frappe.qb.from_(sre)
				.select(sre.name)
				.where(
					(sre.docstatus == 1)
					& (sre.from_voucher_type == from_voucher_type)
					& (sre.from_voucher_no == from_voucher_no)
					& (sre.delivered_qty < sre.reserved_qty)
				)
				.orderby(sre.creation)
			)

			if from_voucher_detail_no:
				query = query.where(sre.from_voucher_detail_no == from_voucher_detail_no)

			sre_list = query.run(as_dict=True)

		sre_list = [d.name for d in sre_list]

	if sre_list:
		for sre in sre_list:
			frappe.get_doc("Stock Reservation Entry", sre).cancel()

		if notify:
			msg = _("Stock Reservation Entries Cancelled")
			frappe.msgprint(msg, alert=True, indicator="red")

def get_stock_reservation_entries_for_voucher(
	voucher_type: str,
	voucher_no: str,
	voucher_detail_no: str | None = None,
	fields: list[str] | None = None,
	ignore_status: bool = False,
) -> list[dict]:
	"""Returns list of Stock Reservation Entries against a Voucher."""

	return _get_stock_reservation_entries_for_voucher(
		voucher_type, voucher_no, voucher_detail_no, fields, ignore_status, ignore_permissions=False
	)

def get_serial_batch_open_qty(sre_names: list[str]) -> dict[str, float]:
	"""Undelivered serial and batch qty of each reservation that has serial and batch entries, read under a lock."""
	if not sre_names:
		return {}

	sb_entry = frappe.qb.DocType("Serial and Batch Entry")
	open_qty = defaultdict(float)
	for parent, qty in (
		frappe.qb.from_(sb_entry)
		.select(sb_entry.parent, sb_entry.qty - sb_entry.delivered_qty)
		.where((sb_entry.parenttype == "Stock Reservation Entry") & sb_entry.parent.isin(sre_names))
		.for_update()
	).run():
		open_qty[parent] += flt(qty)

	return open_qty

def set_delivered_qty(sre: frappe._dict, delivered_qty: float) -> None:
	sre.delivered_qty = delivered_qty
	frappe.db.set_value(
		"Stock Reservation Entry", sre.name, {"delivered_qty": delivered_qty, "status": get_status(sre)}
	)

def get_status(sre) -> str:
	"""Status of a reservation from its docstatus and quantities."""
	if sre.docstatus == 2:
		return "Cancelled"
	if sre.docstatus != 1:
		return "Draft"
	if sre.transferred_qty:
		return "Partially Used" if sre.transferred_qty < sre.reserved_qty else "Closed"
	if flt(sre.delivered_qty) + flt(sre.consumed_qty) >= flt(sre.reserved_qty):
		return "Delivered"
	if sre.delivered_qty:
		return "Partially Delivered"
	if sre.consumed_qty:
		return "Partially Used"
	if sre.reserved_qty >= sre.voucher_qty:
		return "Reserved"
	return "Partially Reserved"

def allocate_serial_batch_qty(
	entries: list[dict], limits: dict[str, float], serial_batch: frappe._dict
) -> dict[str, float]:
	"""Qty to move on each row, within its open qty, the serial and batch qty to move and its reservation's limit."""
	limits = defaultdict(float, limits)
	serial_nos = set(serial_batch.get("serial_nos") or [])
	batches = defaultdict(float, serial_batch.get("batches") or {})
	moved_qty = {}
	for entry in entries:
		qty = 0
		if entry.serial_no and entry.serial_no in serial_nos and limits[entry.parent] >= entry.open_qty:
			qty = entry.open_qty
			serial_nos.remove(entry.serial_no)
		elif not entry.serial_no and entry.batch_no:
			qty = min(entry.open_qty, batches[entry.batch_no], limits[entry.parent])
			batches[entry.batch_no] -= qty

		limits[entry.parent] -= qty
		if qty > 0:
			moved_qty[entry.name] = qty

	return moved_qty

def add_serial_batch_delivered_qty(deltas: dict[str, float]) -> None:
	"""Add each delta to its row's delivered qty, one statement per distinct delta."""
	rows_by_delta = defaultdict(list)
	for name, delta in deltas.items():
		rows_by_delta[delta].append(name)

	sb_entry = frappe.qb.DocType("Serial and Batch Entry")
	for delta, names in rows_by_delta.items():
		frappe.qb.update(sb_entry).set(sb_entry.delivered_qty, sb_entry.delivered_qty + delta).where(
			sb_entry.name.isin(names)
		).run()

def onload(self) -> None:
	if frappe.get_cached_value("Stock Settings", None, "enable_stock_reservation"):
		if self.has_unreserved_stock():
			self.set_onload("has_unreserved_stock", True)

	if self.has_reserved_stock():
		self.set_onload("has_reserved_stock", True)

	if self.docstatus.is_draft() and not hasattr(self, "_action"):
		company = self.company

		for item in self.get("locations"):
			item.update(get_item_details(item.item_code, item.uom, item.warehouse, company))

def set_stock_qty(self):
	if not self.docstatus.is_draft() and getattr(self, "_action", None) != "submit":
		return

	conversion_factors = get_uom_conversion_factors(
		{row.item_code for row in self.locations if row.item_code}
	)
	for row in self.locations:
		if not row.item_code:
			continue

		stock_uom = frappe.get_cached_value("Item", row.item_code, "stock_uom")
		row.uom = row.uom or stock_uom
		if row.uom == stock_uom:
			row.conversion_factor = 1
		elif (row.item_code, row.uom) in conversion_factors:
			row.conversion_factor = conversion_factors[(row.item_code, row.uom)]

		row.stock_qty = flt(flt(row.qty) * flt(row.conversion_factor), row.precision("stock_qty"))

def before_save(self):
	self.update_status()
	if not self.pick_manually:
		self.set_item_locations()

	if self.get("locations"):
		self.validate_sales_order_percentage()
		self.validate_warehouses()

def validate_stock_qty(self):
	from erpnext.stock.doctype.batch.batch import get_batch_qty

	for row in self.get("locations"):
		row_qty = self.get_qty_to_pick(row)
		if not row_qty:
			continue

		if row.batch_no:
			batch_qty = get_batch_qty(row.batch_no, row.warehouse, row.item_code)

			if row_qty > batch_qty:
				frappe.throw(
					_(
						"At Row #{0}: The picked quantity {1} for the item {2} is greater than available stock {3} for the batch {4} in the warehouse {5}. Please restock the item."
					).format(
						row.idx,
						row_qty,
						row.item_code,
						batch_qty,
						row.batch_no,
						bold(row.warehouse),
					),
					title=_("Insufficient Stock"),
				)

			continue

		bin_qty = flt(
			frappe.db.get_value(
				"Bin",
				{"item_code": row.item_code, "warehouse": row.warehouse},
				"actual_qty",
			)
		)

		if row_qty > bin_qty:
			frappe.throw(
				_(
					"At Row #{0}: The picked quantity {1} for the item {2} is greater than available stock {3} in the warehouse {4}."
				).format(row.idx, row_qty, bold(row.item_code), bin_qty, bold(row.warehouse)),
				title=_("Insufficient Stock"),
			)

def get_qty_to_pick(self, row):
	if row.picked_qty or self.scan_mode or not self.docstatus.is_submitted():
		return flt(row.picked_qty)

	return flt(row.stock_qty)

def validate_warehouses(self):
	for location in self.locations:
		if not location.warehouse:
			frappe.throw(
				_("Row {0}: Warehouse is required").format(location.idx),
				title=_("Missing Warehouse"),
				exc=MissingWarehouseValidationError,
			)

		company = frappe.get_cached_value("Warehouse", location.warehouse, "company")

		if company != self.company:
			frappe.throw(
				_(
					"Row {0}: Warehouse {1} is linked to company {2}. Please select a warehouse belonging to company {3}."
				).format(
					location.idx,
					frappe.bold(location.warehouse),
					frappe.bold(company),
					frappe.bold(self.company),
				),
				title=_("Incorrect Warehouse"),
				exc=IncorrectWarehouseValidationError,
			)

def check_serial_no_status(self):
	from erpnext.stock.doctype.serial_no.serial_no import get_serial_nos

	for row in self.get("locations"):
		if not row.serial_no:
			continue

		picked_serial_nos = get_serial_nos(row.serial_no)
		validated_serial_nos = frappe.get_all(
			"Serial No",
			filters={"name": ("in", picked_serial_nos), "warehouse": row.warehouse},
			pluck="name",
		)

		incorrect_serial_nos = set(picked_serial_nos) - set(validated_serial_nos)
		if incorrect_serial_nos:
			frappe.throw(
				_("The Serial No at Row #{0}: {1} is not available in warehouse {2}.").format(
					row.idx, ", ".join(incorrect_serial_nos), row.warehouse
				),
				title=_("Incorrect Warehouse"),
			)

def validate_with_previous_doc(self):
	super().validate_with_previous_doc(
		{
			"Sales Order": {
				"ref_dn_field": "sales_order",
				"compare_fields": [
					["company", "="],
				],
			},
		}
	)

def validate_sales_order_percentage(self):
	# set percentage picked in SO
	for location in self.get("locations"):
		if (
			location.sales_order
			and frappe.db.get_value("Sales Order", location.sales_order, "per_picked", cache=True) == 100
		):
			frappe.throw(
				_("Row #{}: item {} has been picked already.").format(location.idx, location.item_code)
			)

def before_submit(self):
	self.validate_sales_order()
	self.validate_picked_items()

def validate_sales_order(self):
	"""Raises an exception if the `Sales Order` has reserved stock."""

	if self.purpose != "Delivery":
		return

	so_list = set(location.sales_order for location in self.locations if location.sales_order)

	if so_list:
		for so in so_list:
			so_doc = frappe.get_doc("Sales Order", so)
			for item in so_doc.items:
				if item.stock_reserved_qty > 0:
					frappe.throw(
						_(
							"Cannot create a pick list for Sales Order {0} because it has reserved stock. Please unreserve the stock in order to create a pick list."
						).format(frappe.bold(so))
					)

def validate_picked_items(self):
	for item in self.locations:
		if self.scan_mode and item.picked_qty < item.stock_qty:
			frappe.throw(
				_(
					"Row {0} picked quantity is less than the required quantity, additional {1} {2} required."
				).format(item.idx, item.stock_qty - item.picked_qty, item.stock_uom),
				title=_("Pick List Incomplete"),
			)

		if not self.scan_mode and not item.picked_qty:
			# if the user has not entered any picked qty, set it to stock_qty, before submit
			item.picked_qty = item.stock_qty

def validate_expired_batches(self):
	batches = []
	for row in self.get("locations"):
		if row.get("batch_no") and (row.get("picked_qty") or self.pick_manually):
			batches.append(row.batch_no)

	if batches:
		batch = frappe.qb.DocType("Batch")
		query = (
			frappe.qb.from_(batch)
			.select(batch.name)
			.where(
				(batch.name.isin(batches))
				& (batch.expiry_date < frappe.utils.nowdate())
				& (batch.expiry_date.isnotnull())
			)
		)

		expired_batches = query.run(as_dict=True)
		if expired_batches:
			msg = "<ul>" + "".join(f"<li>{batch.name}</li>" for batch in expired_batches) + "</ul>"

			frappe.throw(
				_("The following batches are expired, please restock them: <br> {0}").format(msg),
				title=_("Expired Batches"),
			)

def make_bundle_using_old_serial_batch_fields(self):
	from erpnext.stock.doctype.serial_no.serial_no import get_serial_nos

	for row in self.locations:
		if not row.serial_no and not row.batch_no:
			continue

		if not row.use_serial_batch_fields and (row.serial_no or row.batch_no):
			frappe.throw(_("Please enable Use Old Serial / Batch Fields to make_bundle"))

		if row.use_serial_batch_fields and (not row.serial_and_batch_bundle):
			sn_doc = SerialBatchCreation(
				{
					"item_code": row.item_code,
					"warehouse": row.warehouse,
					"voucher_type": self.doctype,
					"voucher_no": self.name,
					"voucher_detail_no": row.name,
					"qty": row.stock_qty,
					"type_of_transaction": "Outward",
					"company": self.company,
					"serial_nos": get_serial_nos(row.serial_no) if row.serial_no else None,
					"batches": frappe._dict({row.batch_no: row.stock_qty}) if row.batch_no else None,
					"batch_no": row.batch_no,
				}
			).make_serial_and_batch_bundle()

			row.serial_and_batch_bundle = sn_doc.name
			row.db_set("serial_and_batch_bundle", sn_doc.name)

def on_update_after_submit(self) -> None:
	if self.has_reserved_stock():
		msg = _(
			"The Pick List having Stock Reservation Entries cannot be updated. If you need to make changes, we recommend canceling the existing Stock Reservation Entries before updating the Pick List."
		)
		frappe.throw(msg)

def cancel_open_stock_reservation_entries(self):
	from erpnext.stock.doctype.stock_reservation_entry.stock_reservation_entry import (
		cancel_stock_reservation_entries,
	)

	cancel_stock_reservation_entries(
		from_voucher_type="Pick List", from_voucher_no=self.name, notify=False
	)

def delink_serial_and_batch_bundle(self):
	for row in self.locations:
		if (
			row.serial_and_batch_bundle
			and frappe.db.get_value("Serial and Batch Bundle", row.serial_and_batch_bundle, "docstatus")
			== 1
		):
			frappe.db.set_value(
				"Serial and Batch Bundle",
				row.serial_and_batch_bundle,
				{"is_cancelled": 1, "voucher_no": ""},
			)

			frappe.get_doc("Serial and Batch Bundle", row.serial_and_batch_bundle).cancel()
			row.db_set("serial_and_batch_bundle", None)

def on_update(self):
	if self.get("locations"):
		self.linked_serial_and_batch_bundle()

def linked_serial_and_batch_bundle(self):
	for row in self.get("locations"):
		if row.serial_and_batch_bundle:
			frappe.get_doc(
				"Serial and Batch Bundle", row.serial_and_batch_bundle
			).set_serial_and_batch_values(self, row)

def remove_serial_and_batch_bundle(self):
	for row in self.locations:
		if row.serial_and_batch_bundle:
			frappe.delete_doc("Serial and Batch Bundle", row.serial_and_batch_bundle)

def validate_serial_and_batch_bundle(self):
	for row in self.locations:
		if row.serial_and_batch_bundle:
			doc = frappe.get_doc("Serial and Batch Bundle", row.serial_and_batch_bundle)
			if doc.docstatus == 0:
				doc.submit()

def update_status(self, status=None, update_modified=True):
	if not status:
		status = self.get_status().get("status")

	if status:
		self.db_set("status", status)

def stock_entry_exists(self):
	if self.docstatus != 1:
		return False

	if self.purpose == "Delivery":
		return False

	return stock_entry_exists(self.name)

def get_transfer_status(self):
	"""Return the pick list's transfer progress based on how much of the picked qty has been
	moved into submitted Stock Entries (tracked on Pick List Item.transferred_qty).

	Only applies to purposes that move stock via Stock Entry; the Delivery purpose is tracked
	via delivery_status instead. Returns "Completed", "Partially Transferred" or None."""
	if self.purpose == "Delivery":
		return None

	total_picked = sum(flt(row.picked_qty) for row in self.locations)
	if not total_picked:
		return None

	total_transferred = sum(flt(row.transferred_qty) for row in self.locations)
	if total_transferred <= 0:
		return None

	if total_transferred >= total_picked:
		return "Completed"

	return "Partially Transferred"

def update_reference_qty(self):
	packed_items = []
	so_items = []

	for item in self.locations:
		if item.product_bundle_item:
			packed_items.append(item.product_bundle_item)
		elif item.sales_order_item:
			so_items.append(item.sales_order_item)

	if packed_items:
		self.update_packed_items_qty(packed_items)

	if so_items:
		self.update_sales_order_item_qty(so_items)

def update_packed_items_qty(self, packed_items):
	picked_items = get_picked_items_qty(packed_items, contains_packed_items=True)
	self.validate_picked_qty(picked_items, "Packed Item")

	doc_updates = {item: {"picked_qty": 0} for item in set(packed_items)}
	for d in picked_items:
		doc_updates[d.product_bundle_item] = {"picked_qty": flt(d.picked_qty)}

	if doc_updates:
		frappe.db.bulk_update("Packed Item", doc_updates, update_modified=False)

def update_sales_order_item_qty(self, so_items):
	picked_items = get_picked_items_qty(so_items)
	self.validate_picked_qty(picked_items)

	doc_updates = {item: {"picked_qty": 0} for item in set(so_items)}
	for d in picked_items:
		doc_updates[d.sales_order_item] = {"picked_qty": flt(d.picked_qty)}

	if doc_updates:
		frappe.db.bulk_update("Sales Order Item", doc_updates, update_modified=False)

def update_sales_order_picking_status(self) -> None:
	sales_orders = []
	for row in self.locations:
		if row.sales_order and row.sales_order not in sales_orders:
			sales_orders.append(row.sales_order)

	for sales_order in sales_orders:
		frappe.get_doc("Sales Order", sales_order, for_update=True).update_picking_status()

def create_stock_reservation_entries(self, notify=True) -> None:
	"""Creates Stock Reservation Entries for Sales Order Items against Pick List."""
	self.check_permission("write")

	so_items_details_map = {}
	for location in self.locations:
		if location.warehouse and location.sales_order and location.sales_order_item:
			item_details = {
				"sales_order_item": location.sales_order_item,
				"item_code": location.item_code,
				"warehouse": location.warehouse,
				"qty_to_reserve": (flt(location.picked_qty) - flt(location.stock_reserved_qty)),
				"from_voucher_no": location.parent,
				"from_voucher_detail_no": location.name,
				"serial_and_batch_bundle": location.serial_and_batch_bundle,
			}
			so_items_details_map.setdefault(location.sales_order, []).append(item_details)

	if so_items_details_map:
		for so, items_details in so_items_details_map.items():
			so_doc = frappe.get_doc("Sales Order", so)
			so_doc._create_stock_reservation_entries(
				items_details=items_details,
				from_voucher_type="Pick List",
				notify=notify,
			)

def cancel_stock_reservation_entries(self, notify=True) -> None:
	"""Cancel Stock Reservation Entries for Sales Order Items created against Pick List."""
	self.check_permission("write")

	from erpnext.stock.doctype.stock_reservation_entry.stock_reservation_entry import (
		cancel_stock_reservation_entries,
	)

	cancel_stock_reservation_entries(
		from_voucher_type="Pick List", from_voucher_no=self.name, notify=notify
	)

def validate_picked_qty(self, data, ordered_doctype="Sales Order Item"):
	allowance = 1 + flt(frappe.get_single_value("Stock Settings", "over_picking_allowance")) / 100
	qty_field = "qty" if ordered_doctype == "Packed Item" else "stock_qty"
	reference_field = "product_bundle_item" if ordered_doctype == "Packed Item" else "sales_order_item"
	ordered_qty = dict(
		frappe.get_all(
			ordered_doctype,
			filters={"name": ("in", [row.get(reference_field) for row in data])},
			fields=["name", qty_field],
			as_list=True,
		)
	)

	for row in data:
		ordered = flt(ordered_qty.get(row.get(reference_field)))
		if ordered and flt(row.picked_qty, 6) > flt(ordered * allowance, 6):
			frappe.throw(
				_(
					"You are picking more than required quantity for the item {0}. Check if there is any other pick list created for the sales order {1}."
				).format(row.item_code, row.sales_order)
			)

def get_excluded_warehouses(self) -> set:
	excluded = set(
		frappe.get_all(
			"Warehouse", filters={"company": self.company, "warehouse_type": "Transit"}, pluck="name"
		)
	)
	if self.work_order and (
		wip_warehouse := frappe.db.get_value("Work Order", self.work_order, "wip_warehouse")
	):
		excluded.add(wip_warehouse)

	return excluded

def aggregate_item_qty(self):
	locations = self.get("locations")
	self.item_count_map = {}
	# aggregate qty for same item
	item_map = OrderedDict()
	for item in locations:
		if item.picked_qty:
			continue

		if not item.item_code:
			frappe.throw(f"Row #{item.idx}: Item Code is Mandatory")
		if not cint(
			frappe.get_cached_value("Item", item.item_code, "is_stock_item")
		) and not frappe.db.exists("Product Bundle", {"new_item_code": item.item_code, "disabled": 0}):
			continue
		item_code = item.item_code
		reference = item.sales_order_item or item.material_request_item
		key = (item_code, item.uom, item.warehouse, item.batch_no, reference)

		item.idx = None
		item.name = None

		if item_map.get(key):
			item_map[key].qty += item.qty
			item_map[key].stock_qty += flt(item.stock_qty, item.precision("stock_qty"))
		else:
			item_map[key] = item

		# maintain count of each item (useful to limit get query)
		self.item_count_map.setdefault(item_code, 0)
		self.item_count_map[item_code] += flt(item.stock_qty, item.precision("stock_qty"))
	return item_map.values()

def validate_for_qty(self):
	if self.purpose == "Material Transfer for Manufacture" and (
		self.for_qty is None or self.for_qty == 0
	):
		frappe.throw(_("Qty of Finished Goods Item should be greater than 0."))

def before_print(self, settings=None):
	if self.group_same_items:
		self.group_similar_items()

def group_similar_items(self):
	grouped_rows = {}
	for item in self.locations:
		key = (item.item_code, item.warehouse, item.uom, item.batch_no or "")
		if key not in grouped_rows:
			grouped_rows[key] = item
			continue

		grouped_row = grouped_rows[key]
		grouped_row.qty = flt(grouped_row.qty) + flt(item.qty)
		grouped_row.stock_qty = flt(grouped_row.stock_qty) + flt(item.stock_qty)
		grouped_row.picked_qty = flt(grouped_row.picked_qty) + flt(item.picked_qty)

	self.set("locations", list(grouped_rows.values()))
	for idx, item in enumerate(self.locations, start=1):
		item.idx = idx

def get_picked_items_details(self, items):
	picked_items = frappe._dict()

	if not items:
		return picked_items

	items_data = self._get_pick_list_items(items)

	for item_data in items_data:
		key = (item_data.warehouse, item_data.batch_no) if item_data.batch_no else item_data.warehouse
		serial_no = [x for x in item_data.serial_no.split("\n") if x] if item_data.serial_no else None

		if item_data.item_code not in picked_items:
			picked_items[item_data.item_code] = {}

		if item_data.serial_and_batch_bundle:
			if not serial_no:
				serial_no = get_serial_nos_from_bundle(item_data.serial_and_batch_bundle)

			if not item_data.batch_no and not serial_no:
				bundle_batches = get_batches_from_bundle(item_data.serial_and_batch_bundle)
				for batch_no, batch_qty in bundle_batches.items():
					batch_qty = abs(batch_qty)

					key = (item_data.warehouse, batch_no)
					if key not in picked_items[item_data.item_code]:
						picked_items[item_data.item_code][key] = {"picked_qty": 0}
					picked_items[item_data.item_code][key]["picked_qty"] += batch_qty

				continue

		if key not in picked_items[item_data.item_code]:
			picked_items[item_data.item_code][key] = frappe._dict(
				{
					"picked_qty": 0,
					"serial_no": [],
					"batch_no": item_data.batch_no or "",
					"warehouse": item_data.warehouse,
				}
			)

		picked_items[item_data.item_code][key]["picked_qty"] += item_data.picked_qty
		if serial_no:
			picked_items[item_data.item_code][key]["serial_no"].extend(serial_no)

	self.update_picked_item_from_current_pick_list(picked_items)
	return picked_items

def update_picked_item_from_current_pick_list(self, picked_items):
	for row in self.locations:
		if flt(row.picked_qty) > 0:
			key = (row.warehouse, row.batch_no) if row.batch_no else row.warehouse
			serial_no = [x for x in row.serial_no.split("\n") if x] if row.serial_no else None
			if row.item_code not in picked_items:
				picked_items[row.item_code] = {}

			if key not in picked_items[row.item_code]:
				picked_items[row.item_code][key] = frappe._dict(
					{
						"picked_qty": 0,
						"serial_no": [],
						"batch_no": row.batch_no or "",
						"warehouse": row.warehouse,
					}
				)

			picked_items[row.item_code][key]["picked_qty"] += flt(row.stock_qty) or flt(row.picked_qty)
			if serial_no:
				picked_items[row.item_code][key]["serial_no"].extend(serial_no)

def _get_product_bundles(self) -> dict[str, str]:
	# Dict[so_item_row: item_code]
	product_bundles = {}
	for item in self.locations:
		if not item.product_bundle_item:
			continue

		product_bundles[item.sales_order_item] = frappe._dict(
			{
				"item_code": frappe.db.get_value(
					"Sales Order Item",
					item.sales_order_item,
					"item_code",
				),
				"pick_list_item": item.name,
			}
		)
	return product_bundles

def _get_product_bundle_qty_map(self, bundles) -> dict[str, dict[str, float]]:
	product_bundle_qty_map = {}
	for data in bundles:
		bundle = frappe.get_last_doc("Product Bundle", {"new_item_code": data.item_code, "disabled": 0})
		product_bundle_qty_map[data.item_code] = {item.item_code: item.qty for item in bundle.items}
	return product_bundle_qty_map

def _compute_picked_qty_for_bundle(self, bundle_row, bundle_items) -> int:
	"""Compute how many full bundles can be created from picked items."""
	precision = frappe.get_precision("Stock Ledger Entry", "qty_after_transaction")
	possible_bundles = {}
	for item in self.locations:
		if item.sales_order_item != bundle_row:
			continue

		if qty_in_bundle := bundle_items.get(item.item_code):
			possible_bundles.setdefault(item.product_bundle_item, 0)
			possible_bundles[item.product_bundle_item] += item.picked_qty / qty_in_bundle

	return int(flt(min(possible_bundles.values()), precision or 6)) if possible_bundles else 0

def has_unreserved_stock(self):
	if self.purpose == "Delivery":
		for location in self.locations:
			if (
				location.sales_order
				and location.sales_order_item
				and (flt(location.picked_qty) - flt(location.stock_reserved_qty)) > 0
			):
				return True

	return False

def has_reserved_stock(self):
	if self.purpose == "Delivery":
		for location in self.locations:
			if (
				location.sales_order
				and location.sales_order_item
				and flt(location.stock_reserved_qty) > 0
			):
				return True

	return False

def update_pick_list_status(pick_list):
	if pick_list:
		doc = frappe.get_doc("Pick List", pick_list)
		doc.run_method("update_status")

def get_picked_items_qty(items, contains_packed_items=False) -> list[dict]:
	pi_item = frappe.qb.DocType("Pick List Item")

	query = (
		frappe.qb.from_(pi_item)
		.select(
			pi_item.sales_order_item,
			pi_item.product_bundle_item,
			pi_item.item_code,
			pi_item.sales_order,
			Sum(pi_item.stock_qty).as_("stock_qty"),
			Sum(pi_item.picked_qty).as_("picked_qty"),
		)
		.where(pi_item.docstatus == 1)
		.for_update()
	)

	if contains_packed_items:
		query = query.groupby(
			pi_item.product_bundle_item,
			pi_item.sales_order,
		).where(pi_item.product_bundle_item.isin(items))
	else:
		query = query.groupby(
			pi_item.sales_order_item,
			pi_item.sales_order,
		).where(pi_item.sales_order_item.isin(items))

	return query.run(as_dict=True)

def validate_item_locations(pick_list):
	if not pick_list.locations:
		frappe.throw(_("Add items in the Item Locations table"))

def get_delivered_sales_order_item_query(pi_item):
	so_item = frappe.qb.DocType("Sales Order Item")
	return (
		frappe.qb.from_(so_item)
		.select(so_item.name)
		.where((so_item.name == pi_item.sales_order_item) & (so_item.delivered_qty >= so_item.qty))
	)

def get_uom_conversion_factors(item_codes) -> dict:
	if not item_codes:
		return {}

	return {
		(row.parent, row.uom): flt(row.conversion_factor)
		for row in frappe.get_all(
			"UOM Conversion Detail",
			filters={"parent": ("in", list(item_codes)), "parenttype": "Item"},
			fields=["parent", "uom", "conversion_factor"],
		)
	}

def prioritize_locations(locations, priority_warehouses):
	if not priority_warehouses:
		return locations

	priority_locations = [loc for loc in locations if loc.warehouse in priority_warehouses]
	fallback_locations = [loc for loc in locations if loc.warehouse not in priority_warehouses]
	return priority_locations + fallback_locations

def get_locations_based_on_required_qty(locations, required_qty, priority_warehouses):
	filtered_locations = []

	for location in prioritize_locations(locations, priority_warehouses):
		if location.qty >= required_qty:
			location.qty = required_qty
			filtered_locations.append(location)
			break

		required_qty -= location.qty
		filtered_locations.append(location)

	return filtered_locations

def validate_picked_materials(item_code, required_qty, locations, picked_item_details=None):
	for location in list(locations):
		if location["qty"] < 0:
			locations.remove(location)

	total_qty_available = sum(location.get("qty") for location in locations)
	remaining_qty = required_qty - total_qty_available

	if remaining_qty > 0:
		if picked_item_details:
			frappe.msgprint(
				_(
					"{0} units of Item {1} is not available in any of the warehouses. Other Pick Lists exist for this item."
				).format(remaining_qty, get_link_to_form("Item", item_code)),
				title=_("Already Picked"),
			)
		else:
			frappe.msgprint(
				_("{0} units of Item {1} is not available in any of the warehouses.").format(
					remaining_qty, get_link_to_form("Item", item_code)
				),
				title=_("Insufficient Stock"),
			)

def filter_locations_by_picked_materials(locations, picked_item_details) -> list[dict]:
	filterd_locations = []
	precision = frappe.get_precision("Pick List Item", "qty")
	for row in locations:
		key = row.warehouse
		if row.batch_no:
			key = (row.warehouse, row.batch_no)

		picked_qty = picked_item_details.get(key, {}).get("picked_qty", 0)
		if not picked_qty:
			filterd_locations.append(row)
			continue
		if picked_qty > row.qty:
			row.qty = 0
			picked_item_details[key]["picked_qty"] -= row.qty
		else:
			row.qty -= picked_qty
			picked_item_details[key]["picked_qty"] = 0.0
			if row.serial_nos:
				row.serial_nos = list(set(row.serial_nos) - set(picked_item_details[key].get("serial_no")))

		if flt(row.qty, precision) > 0:
			filterd_locations.append(row)

	return filterd_locations

def get_available_item_locations_for_serialized_item(
	item_code,
	from_warehouses,
	company,
	consider_rejected_warehouses=False,
):
	sn = frappe.qb.DocType("Serial No")
	query = (
		frappe.qb.from_(sn)
		.select(sn.name, sn.warehouse)
		.where(sn.item_code == item_code)
		.orderby(sn.creation)
	)

	if from_warehouses:
		query = query.where(sn.warehouse.isin(from_warehouses))
	else:
		query = query.where(Coalesce(sn.warehouse, "") != "")
		query = query.where(sn.company == company)

	if not consider_rejected_warehouses:
		if rejected_warehouses := get_rejected_warehouses():
			query = query.where(sn.warehouse.notin(rejected_warehouses))

	serial_nos = query.run(as_list=True)

	warehouse_serial_nos_map = frappe._dict()
	for serial_no, warehouse in serial_nos:
		warehouse_serial_nos_map.setdefault(warehouse, []).append(serial_no)

	locations = []

	for warehouse, serial_nos in warehouse_serial_nos_map.items():
		qty = len(serial_nos)

		locations.append(
			frappe._dict(
				{
					"qty": qty,
					"warehouse": warehouse,
					"item_code": item_code,
					"serial_nos": serial_nos,
				}
			)
		)

	return locations

def get_available_item_locations_for_batched_item(
	item_code,
	from_warehouses,
	company,
	consider_rejected_warehouses=False,
):
	locations = []
	data = get_auto_batch_nos(
		frappe._dict(
			{
				"item_code": item_code,
				"warehouse": from_warehouses,
				"company": company,
				"based_on": frappe.get_single_value("Stock Settings", "pick_serial_and_batch_based_on"),
			}
		)
	)

	warehouse_wise_batches = frappe._dict()
	rejected_warehouses = get_rejected_warehouses()

	for d in data:
		if not consider_rejected_warehouses and rejected_warehouses and d.warehouse in rejected_warehouses:
			continue

		if d.warehouse not in warehouse_wise_batches:
			warehouse_wise_batches.setdefault(d.warehouse, defaultdict(float))

		warehouse_wise_batches[d.warehouse][d.batch_no] += d.qty

	for warehouse, batches in warehouse_wise_batches.items():
		for batch_no, qty in batches.items():
			locations.append(
				frappe._dict(
					{
						"qty": qty,
						"warehouse": warehouse,
						"item_code": item_code,
						"batch_no": batch_no,
					}
				)
			)

	return locations

def get_available_item_locations_for_other_item(
	item_code,
	from_warehouses,
	company,
	consider_rejected_warehouses=False,
):
	bin = frappe.qb.DocType("Bin")
	query = (
		frappe.qb.from_(bin)
		.select(bin.warehouse, bin.actual_qty.as_("qty"))
		.where((bin.item_code == item_code) & (bin.actual_qty > 0))
		.orderby(bin.creation)
	)

	if from_warehouses:
		query = query.where(bin.warehouse.isin(from_warehouses))
	else:
		wh = frappe.qb.DocType("Warehouse")
		query = query.from_(wh).where((bin.warehouse == wh.name) & (wh.company == company))

	if not consider_rejected_warehouses:
		if rejected_warehouses := get_rejected_warehouses():
			query = query.where(bin.warehouse.notin(rejected_warehouses))

	item_locations = query.run(as_dict=True)

	return item_locations

def create_delivery(
	source_name: str, target_doc: str | dict | Document | None = None, target: str | None = None
):
	pick_list = frappe.get_doc("Pick List", source_name)
	pick_list.check_permission("read")
	target = target or (frappe.flags.args or {}).get("target") or "Delivery Note"
	validate_item_locations(pick_list)
	sales_dict = dict()
	documents = []
	sales_orders = get_sales_order_headers({location.sales_order for location in pick_list.locations})

	for key, rows in groupby(sorted(sales_orders, key=get_header_key), key=get_header_key):
		sales_dict[key] = {row.sales_order for row in rows}

	if sales_dict:
		documents.extend(create_delivery_with_so(sales_dict, pick_list, target))

	if not all(item.sales_order for item in pick_list.locations):
		documents.append(create_delivery_wo_so(pick_list, target, target_doc))

	if len(documents) == 1:
		return documents[0]
	else:
		from frappe.utils import comma_and

		doc_list = [get_link_to_form(target, p.name) for p in documents]
		frappe.msgprint(_("{0} created").format(comma_and(doc_list)))

def get_header_key(sales_order):
	key = tuple(cstr(sales_order.get(field)) for field in SALES_ORDER_HEADER_FIELDS)
	key += (
		tuple(
			tuple(cstr(tax.get(field)) for field in SALES_ORDER_TAX_KEY_FIELDS) for tax in sales_order.taxes
		),
	)
	if has_order_specific_amounts(sales_order):
		key += (sales_order.sales_order,)

	return key

def has_order_specific_amounts(sales_order):
	if flt(sales_order.discount_amount) and not flt(sales_order.additional_discount_percentage):
		return True

	return any(tax.charge_type == "Actual" for tax in sales_order.taxes)

def get_sales_order_headers(sales_orders):
	sales_orders = [so for so in sales_orders if so]
	if not sales_orders:
		return []

	headers = frappe.get_all(
		"Sales Order",
		filters={"name": ("in", sales_orders)},
		fields=["name as sales_order", *SALES_ORDER_HEADER_FIELDS],
	)
	taxes = get_sales_order_taxes(sales_orders)
	for header in headers:
		header.taxes = taxes.get(header.sales_order, [])

	return headers

def get_sales_order_taxes(sales_orders):
	tax = frappe.qb.DocType("Sales Taxes and Charges")
	rows = (
		frappe.qb.from_(tax)
		.select(tax.parent, *[tax[field] for field in SALES_ORDER_TAX_KEY_FIELDS])
		.where((tax.parenttype == "Sales Order") & (tax.parent.isin(sales_orders)))
		.orderby(tax.parent)
		.orderby(tax.idx)
	).run(as_dict=True)

	taxes = {}
	for row in rows:
		taxes.setdefault(row.parent, []).append(row)

	return taxes

def create_delivery_wo_so(pick_list, target, target_doc=None, selected_locations=None):
	if not target_doc:
		target_doc = frappe.new_doc(target)

	target_doc.company = pick_list.company

	if not target_doc.customer:
		target_doc.customer = pick_list.customer

	item_table_mapper_without_so = {
		"doctype": f"{target} Item",
		"field_map": {
			"rate": "rate",
			"name": "name",
			"parent": "",
		},
	}
	map_pl_locations(
		pick_list, item_table_mapper_without_so, target_doc, selected_locations=selected_locations
	)
	target_doc.flags.ignore_mandatory = True
	if target == "Sales Invoice":
		target_doc.update_stock = 1
	target_doc.save()

	return target_doc

def create_dn_for_pick_lists(
	source_name: str, target_doc: str | dict | Document | None = None, kwargs: str | dict | None = None
):
	"""Get Items from Multiple Pick Lists and create a Delivery Note for filtered customer"""
	if kwargs is None:
		kwargs = {}
	if isinstance(kwargs, str):
		kwargs = json.loads(kwargs)

	pick_list = frappe.get_doc("Pick List", source_name)
	pick_list.check_permission("read")
	validate_item_locations(pick_list)

	sales_order_arg = kwargs.get("sales_order")
	customer_arg = kwargs.get("customer")

	if sales_order_arg:
		sales_orders = {sales_order_arg}
	else:
		sales_orders = {row.sales_order for row in pick_list.locations if row.sales_order}

		if customer_arg:
			sales_orders = frappe.get_all(
				"Sales Order",
				filters={"customer": customer_arg, "name": ["in", list(sales_orders)]},
				pluck="name",
			)

	delivery_note = create_delivery_from_so(
		pick_list, sales_orders, "Delivery Note", target_doc=target_doc, kwargs=kwargs
	)

	if not sales_order_arg and not all(item.sales_order for item in pick_list.locations):
		if isinstance(delivery_note, str):
			delivery_note = frappe.get_doc(frappe.parse_json(delivery_note))

		delivery_note = create_delivery_wo_so(
			pick_list, "Delivery Note", delivery_note, set(kwargs.get("filtered_children") or [])
		)

	return delivery_note

def create_dn_from_so(pick_list, sales_order_list, delivery_note=None, kwargs=None):
	return create_delivery_from_so(
		pick_list, sales_order_list, "Delivery Note", target_doc=delivery_note, kwargs=kwargs
	)

def create_delivery_from_so(pick_list, sales_order_list, target, target_doc=None, kwargs=None):
	if not sales_order_list:
		return target_doc

	if kwargs is None:
		kwargs = {}

	item_table_mapper = {
		"doctype": f"{target} Item",
		"field_map": {
			"rate": "rate",
			"name": "so_detail",
			"parent": "against_sales_order" if target == "Delivery Note" else "sales_order",
		},
		"condition": lambda doc: abs(doc.delivered_qty) < abs(doc.qty) and doc.delivered_by_supplier != 1,
	}
	selected_locations = set(kwargs.get("filtered_children") or [])

	mapper_kwargs = {"skip_item_mapping": True, "ignore_pricing_rule": pick_list.ignore_pricing_rule}

	target_doc = (
		create_delivery_note_from_sales_order(next(iter(sales_order_list)), target_doc, kwargs=mapper_kwargs)
		if target == "Delivery Note"
		else create_sales_invoice_from_sales_order(
			next(iter(sales_order_list)), target_doc, args=mapper_kwargs
		)
	)

	if not target_doc:
		return

	for so in sales_order_list:
		map_pl_locations(pick_list, item_table_mapper, target_doc, so, selected_locations)

	return target_doc

def map_pl_locations(pick_list, item_mapper, target_doc, sales_order=None, selected_locations=None):
	sales_order_items = (
		{d.name: d for d in frappe.get_doc("Sales Order", sales_order).items} if sales_order else {}
	)
	condition = item_mapper.get("condition")

	for location in pick_list.locations:
		if location.sales_order != sales_order or location.product_bundle_item:
			continue

		if flt(location.picked_qty) - flt(location.delivered_qty) <= 0:
			continue

		if selected_locations and location.name not in selected_locations:
			continue

		sales_order_item = sales_order_items.get(location.sales_order_item)
		if sales_order_item and condition and not condition(sales_order_item):
			continue

		source_doc = sales_order_item or location

		child_item = map_child_doc(source_doc, target_doc, item_mapper)

		if child_item:
			child_item.against_pick_list = pick_list.name
			child_item.pick_list_item = location.name
			child_item.warehouse = location.warehouse
			child_item.qty = flt(location.picked_qty - location.delivered_qty) / (
				flt(child_item.conversion_factor) or 1
			)
			child_item.batch_no = location.batch_no
			child_item.serial_no = location.serial_no
			child_item.use_serial_batch_fields = location.use_serial_batch_fields

			if not child_item.qty:
				target_doc.items.remove(child_item)
				continue

			update_child_item(source_doc, child_item, target_doc)

	if sales_order:
		add_product_bundles_to_target(pick_list, target_doc, item_mapper, sales_order, selected_locations)

	set_target_missing_values(target_doc)

	target_doc.company = pick_list.company
	if sales_order:
		target_doc.customer = frappe.get_value("Sales Order", sales_order, "customer")

def add_product_bundles_to_delivery_note(
	pick_list: "PickList", delivery_note, item_mapper, sales_order=None
) -> None:
	return add_product_bundles_to_target(pick_list, delivery_note, item_mapper, sales_order)

def add_product_bundles_to_target(
	pick_list, target_doc, item_mapper, sales_order=None, selected_locations=None
) -> None:
	"""Add product bundles found in pick list to target document.

	When mapping pick list items, the bundle item itself isn't part of the
	locations. Dynamically fetch and add parent bundle item into target document."""
	product_bundles = pick_list._get_product_bundles()
	if selected_locations:
		selected_bundles = {
			row.sales_order_item
			for row in pick_list.locations
			if row.product_bundle_item and row.name in selected_locations
		}
		product_bundles = {key: value for key, value in product_bundles.items() if key in selected_bundles}

	product_bundle_qty_map = pick_list._get_product_bundle_qty_map(product_bundles.values())

	for so_row, value in product_bundles.items():
		sales_order_item = frappe.get_doc("Sales Order Item", so_row)
		if sales_order and sales_order_item.parent != sales_order:
			continue

		target_bundle_item = map_child_doc(sales_order_item, target_doc, item_mapper)
		target_bundle_item.qty = pick_list._compute_picked_qty_for_bundle(
			so_row, product_bundle_qty_map[value.item_code]
		)
		target_bundle_item.pick_list_item = value.pick_list_item
		target_bundle_item.against_pick_list = pick_list.name
		update_child_item(sales_order_item, target_bundle_item, target_doc)

def create_stock_entry(pick_list: str | dict):
	pick_list = frappe.get_doc(frappe.parse_json(pick_list))
	pick_list.check_permission("read")
	validate_item_locations(pick_list)

	stock_entry = frappe.new_doc("Stock Entry")
	stock_entry.pick_list = pick_list.get("name")
	stock_entry.purpose = pick_list.get("purpose")
	stock_entry.company = pick_list.get("company")

	job_card = pick_list.get("material_request") and frappe.db.get_value(
		"Material Request", pick_list.get("material_request"), "job_card"
	)

	if job_card:
		stock_entry = update_stock_entry_based_on_job_card(pick_list, stock_entry, job_card)
	elif pick_list.get("work_order"):
		stock_entry = update_stock_entry_based_on_work_order(pick_list, stock_entry)
	elif pick_list.get("material_request"):
		stock_entry = update_stock_entry_based_on_material_request(pick_list, stock_entry)
	else:
		stock_entry = update_stock_entry_items_with_no_reference(pick_list, stock_entry)

	stock_entry.set_stock_entry_type()

	if not stock_entry.get("items"):
		return frappe.msgprint(_("All picked items have already been transferred against this Pick List"))

	stock_entry.set_missing_values()

	return stock_entry.as_dict()

def get_item_details(item_code, uom=None, warehouse=None, company=None):
	frappe.has_permission("Pick List", throw=True)
	details = frappe.db.get_value("Item", item_code, "stock_uom", as_dict=1)
	details.uom = uom or details.stock_uom
	if uom:
		details.update(get_conversion_factor(item_code, uom))

	if warehouse:
		details.actual_qty = flt(get_actual_qty(item_code, warehouse))

	if company:
		details.company_total_stock = get_company_total_stock(item_code, company)

	return details

def get_actual_qty(item_code, warehouse):
	return frappe.db.get_value(
		"Bin",
		{"item_code": item_code, "warehouse": warehouse},
		"actual_qty",
	)

def update_child_item(source, target, target_doc):
	cost_center = frappe.db.get_value("Project", target_doc.project, "cost_center")
	if not cost_center:
		cost_center = get_cost_center(source.item_code, "Item", target_doc.company)

	if not cost_center:
		cost_center = get_cost_center(source.item_group, "Item Group", target_doc.company)

	target.cost_center = cost_center

def get_cost_center(for_item, from_doctype, company):
	"""Returns Cost Center for Item or Item Group"""
	return frappe.db.get_value(
		"Item Default",
		fieldname=["buying_cost_center"],
		filters={"parent": for_item, "parenttype": from_doctype, "company": company},
	)

def get_job_card_items_by_material_request_item(pick_list):
	material_request_items = [
		location.material_request_item for location in pick_list.locations if location.material_request_item
	]
	if not material_request_items:
		return {}

	return dict(
		frappe.get_all(
			"Material Request Item",
			filters={"name": ["in", material_request_items]},
			fields=["name", "job_card_item"],
			as_list=True,
		)
	)

def update_stock_entry_based_on_material_request(pick_list, stock_entry):
	for location in pick_list.locations:
		if get_pending_transfer_stock_qty(location) <= 0:
			continue
		target_warehouse = None
		if location.material_request_item:
			target_warehouse = frappe.get_value(
				"Material Request Item", location.material_request_item, "warehouse"
			)
		item = frappe._dict()
		update_common_item_properties(item, location)
		item.t_warehouse = target_warehouse
		stock_entry.append("items", item)

	return stock_entry

def update_stock_entry_items_with_no_reference(pick_list, stock_entry):
	for location in pick_list.locations:
		if get_pending_transfer_stock_qty(location) <= 0:
			continue
		item = frappe._dict()
		update_common_item_properties(item, location)

		stock_entry.append("items", item)

	return stock_entry

def get_pending_transfer_stock_qty(location):
	"""Stock qty of this pick list row still to be moved into a Stock Entry."""
	return flt(location.picked_qty) - flt(location.transferred_qty)

def get_rejected_warehouses():
	if not hasattr(frappe.local, "rejected_warehouses"):
		frappe.local.rejected_warehouses = []

	if not frappe.local.rejected_warehouses:
		frappe.local.rejected_warehouses = frappe.get_all(
			"Warehouse", filters={"is_rejected_warehouse": 1}, pluck="name"
		)

	return frappe.local.rejected_warehouses
